function cedulaDeSesion(sess) {
  let c = String(sess.cedula || sess.numero_documento || '').replace(/\D/g, '');
  if (c) return c;
  const ref = String(sess.referencia || '').trim().toUpperCase();
  const list = Array.isArray(sess.referencias) ? sess.referencias : [];
  if (ref && list.length) {
    for (const r of list) {
      if (String(r.referencia || '').trim().toUpperCase() === ref) {
        return String(r.cedula || '').replace(/\D/g, '');
      }
    }
  }
  return '';
}

const sess = sessionFrom();
const cedula = cedulaDeSesion(sess);
if (!cedula) {
  return JSON.stringify({
    ok: false,
    cedula: '',
    message: 'Falta la cédula. Pide solo el número, dígitos, sin puntos ni comas. No inventes radicados ni digas que ya consultaste.'
  });
}
return JSON.stringify({
  ok: true,
  cedula: cedula,
  message: 'La consulta corre en este turno. No redactes el listado ni digas que registraste una PQR. El mensaje, el enlace y los botones los escribe el flujo.'
});

