const sess = sessionFrom();
const referencia = String(sess.referencia || '').trim();
const cedula = String(sess.cedula || sess.numero_documento || '').replace(/\D/g, '');
const nombre = String(sess.nombre_cliente || '').trim();
if (!referencia && !cedula) {
  return JSON.stringify({
    ok: false,
    message: 'Aún no hay cédula ni referencia en la sesión. Pide la cédula, solo dígitos, o la referencia BH. No inventes planes ni estados.'
  });
}
return JSON.stringify({
  ok: true,
  referencia: referencia,
  cedula: cedula,
  nombre: nombre,
  message: 'Esos datos ya están en la sesión. No vuelvas a consultar SIMA ni pidas otra vez el documento. No inventes planes ni saldos.'
});

let prev = $('Router Menú').first().json;
try { if ($('Interpretar identidad').isExecuted) prev = $('Interpretar identidad').first().json; } catch (e) {}
try { if ($('Armar factura').isExecuted) prev = $('Armar factura').first().json; } catch (e) {}
let out = $input.first().json || {};
try {
  const agentes = ['Agente Soporte', 'Agente Facturación', 'Agente Ventas'];
  for (const nombre of agentes) {
    if ($(nombre).isExecuted) {
      const aj = $(nombre).first().json || {};
      if ((out.output === undefined || out.output === null || out.output === '') && aj.output !== undefined) {
        out = Object.assign({}, aj, out);
      }
      break;
    }
  }
} catch (e) {}
let reply = String(out.output !== undefined ? out.output : (out.text || '')).trim();
function textoDe(nodeName, field) {
  try {
    if (!$(nodeName).isExecuted) return '';
    const j = $(nodeName).first().json || {};
    return String(j[field] || '').trim();
  } catch (e) { return ''; }
}
const preferido = textoDe('Respuesta Reinicio', 'output')
  || textoDe('Respuesta Búsqueda', 'output')
  || textoDe('Respuesta PQRS', 'output_pqrs')
  || textoDe('Respuesta inventario', 'output')
  || textoDe('Respuesta ordenes', 'output')
  || textoDe('Respuesta recibos', 'output');
if (preferido) reply = preferido;
if (!reply) reply = 'No pude generar una respuesta. Intenta de nuevo en un momento.';
if (reply.length > 4000) reply = reply.slice(0, 3900) + '\n…';

const session = Object.assign({}, prev.session || {});

function ran(name) {
  try { return $(name).isExecuted; } catch (e) { return false; }
}

function collectToolNames(obj, acc, depth) {
  if (!obj || typeof obj !== 'object' || depth > 8) return;
  if (Array.isArray(obj)) {
    obj.forEach((x) => collectToolNames(x, acc, depth + 1));
    return;
  }
  for (const [k, v] of Object.entries(obj)) {
    if ((k === 'tool' || k === 'toolName' || k === 'name') && typeof v === 'string') acc.push(v);
    if (k === 'action' && v && typeof v === 'object' && typeof v.tool === 'string') acc.push(v.tool);
    if (v && typeof v === 'object') collectToolNames(v, acc, depth + 1);
  }
}

if (ran('Transfer Ventas')) session.active_agent = 'ventas';
else if (ran('Transfer Facturación')) session.active_agent = 'facturacion';
else if (ran('Transfer Soporte desde Facturación') || ran('Transfer Soporte desde Ventas')) session.active_agent = 'soporte';
else {
  const names = [];
  collectToolNames(out.intermediateSteps || out.intermediate_steps || [], names, 0);
  const blob = names.join(' | ').toLowerCase();
  if (/\btransfer ventas\b/.test(blob)) session.active_agent = 'ventas';
  else if (/transfer factur/.test(blob)) session.active_agent = 'facturacion';
  else if (/transfer soporte/.test(blob)) session.active_agent = 'soporte';
}

const agentePrevio = String((prev.session || {}).active_agent || '');
const sinIdentidad = !session.referencia && !session.cedula && !session.numero_documento;
const estadoMenu = String(session.menu_state || '');
if (session.active_agent === 'facturacion' && sinIdentidad && (estadoMenu === 'done' || estadoMenu === '' || agentePrevio !== 'facturacion')) {
  session.area_destino = 'facturacion';
  session.menu_state = 'doc_dato';
  session.motivo = '';
  reply = 'Para consultar tu cuenta escribe tu cédula de ciudadanía, solo dígitos y sin puntos ni comas, o tu referencia (ejemplo BH00000).';
}

let handoff_team = '';
if (prev.cerrar_chat === true || out.cerrar_chat === true) handoff_team = '';
else if (ran('Handoff Ventas Humano')) handoff_team = 'ventas';
else if (ran('Handoff Contabilidad')) handoff_team = 'contabilidad';
else if (ran('Handoff Humano Soporte')) handoff_team = 'soporte';
else {
  const names = [];
  collectToolNames(out.intermediateSteps || out.intermediate_steps || [], names, 0);
  const blob = names.join(' | ').toLowerCase();
  if (/handoff ventas/.test(blob) || /\bhandoff:["']?ventas/.test(blob)) handoff_team = 'ventas';
  else if (/handoff contabilidad/.test(blob)) handoff_team = 'contabilidad';
  else if (/handoff humano soporte/.test(blob)) handoff_team = 'soporte';
}
if (!handoff_team && prev.cerrar_chat !== true && out.cerrar_chat !== true) {
  const hinted = String(prev.handoff_team || out.handoff_team || '').toLowerCase();
  if (hinted === 'soporte' || hinted === 'ventas' || hinted === 'contabilidad') handoff_team = hinted;
}

let cfg = {};
try { cfg = $('Config').first().json || {}; } catch (e) {}
let norm = {};
try { norm = $('Normalize').first().json || {}; } catch (e) {}

const teamMap = {
  ventas: Number(cfg.team_id_ventas || prev.team_id_ventas || 0),
  contabilidad: Number(cfg.team_id_contabilidad || prev.team_id_contabilidad || 0),
  soporte: Number(cfg.team_id_soporte || prev.team_id_soporte || 0)
};
let handoff_team_id = handoff_team ? (teamMap[handoff_team] || 0) : 0;
const asesorApagado = cfg.asesor_humano === false || cfg.asesor_humano === 0 || String(cfg.asesor_humano) === 'false';
if (asesorApagado) {
