function matchSoporte(n) {
  if (n === '1' || n.indexOf('1 ') === 0) return 'falla_tecnica';
  if (n === '2' || n.indexOf('2 ') === 0) return 'cambio_wifi';
  if (n === '3' || n.indexOf('3 ') === 0) return 'pqr';
  if (n.indexOf('wifi') !== -1 || n.indexOf('wi fi') !== -1 || n.indexOf('contrasena') !== -1 || n.indexOf('clave') !== -1) return 'cambio_wifi';
  if (n.indexOf('pqr') !== -1 || n.indexOf('queja') !== -1 || n.indexOf('reclamo') !== -1 || n.indexOf('peticion') !== -1) return 'pqr';
  if (n.indexOf('soporte tecnico') !== -1 || n.indexOf('internet') !== -1 || n.indexOf(' tv') !== -1 || n === 'tv' || n === 'soporte') return 'falla_tecnica';
  return '';
}

