function clasificarDato(raw) {
  const original = String(raw || '').trim();
  const sinPuntuacion = original.replace(/[\s.,]/g, '');
  if (!sinPuntuacion) return { error: 'formato' };
  if (/^\d+$/.test(sinPuntuacion)) {
    if (sinPuntuacion.length < 5 || sinPuntuacion.length > 15) return { error: 'cedula_len' };
    return { kind: 'cedula', numero: sinPuntuacion };
  }
  if (/[.,\s]/.test(original)) return { error: 'formato' };
  if (/^BH\d+$/i.test(original)) {
    if (original.length < 3 || original.length > 20) return { error: 'formato' };
    return { kind: 'referencia', referencia: original.toUpperCase() };
  }
  return { error: 'formato' };
}

