function esCuenta(n) {
  return n.indexOf('plan de pago') !== -1
    || n.indexOf('saldo') !== -1
    || n.indexOf('factura') !== -1
    || n.indexOf('estado de cuenta') !== -1
    || n.indexOf('deuda') !== -1
    || n.indexOf('recibo') !== -1
    || n.indexOf('fecha de corte') !== -1
    || n.indexOf('pagar') !== -1
    || n.indexOf('pago') !== -1
    || n.indexOf('pague') !== -1
    || tienePalabra(n, 'debo')
    || n.indexOf('cobro') !== -1
    || n.indexOf('mensualidad') !== -1;
}

function tienePalabra(n, palabra) {
  return (' ' + n + ' ').indexOf(' ' + palabra + ' ') !== -1;
}

function pidePlanes(n) {
  if (n.indexOf('plan de pago') !== -1) return false;
  return n.indexOf('precio') !== -1
