    || n.indexOf('cobertura') !== -1
    || n.indexOf('tarifa') !== -1
    || n.indexOf('contratar') !== -1
    || n.indexOf('contratacion') !== -1
    || tienePalabra(n, 'plan')
    || tienePalabra(n, 'planes');
}

function pideSoporte(n) {
  return tienePalabra(n, 'falla')
    || n.indexOf('no funciona') !== -1
    || n.indexOf('no sirve') !== -1
    || n.indexOf('sin servicio') !== -1
    || n.indexOf('se cayo') !== -1
