function payloadDe(json) {
  if (!json || typeof json !== 'object') return [];
  let body = json.body !== undefined ? json.body : json;
  if (typeof body === 'string') {
    try { body = JSON.parse(body); } catch (e) { return []; }
  }
  if (!body || typeof body !== 'object' || Array.isArray(body)) {
    return Array.isArray(body) ? body : [];
  }
  const data = body.data && typeof body.data === 'object' && !Array.isArray(body.data) ? body.data : body;
  if (Array.isArray(data.payload)) return data.payload;
  if (Array.isArray(body.payload)) return body.payload;
  if (Array.isArray(body.data)) return body.data;
  return [];
}

function epochDe(valor) {
  if (valor === undefined || valor === null || valor === '') return 0;
  if (typeof valor === 'number') {
    if (!valor) return 0;
    return valor > 1e12 ? Math.floor(valor / 1000) : Math.floor(valor);
  }
  const texto = String(valor).trim();
  if (/^\d+(\.\d+)?$/.test(texto)) {
    const n = Number(texto);
    if (!n) return 0;
    return n > 1e12 ? Math.floor(n / 1000) : Math.floor(n);
  }
  const parsed = Date.parse(texto);
  if (!parsed) return 0;
  return Math.floor(parsed / 1000);
}

function esActividad(m) {
  const tipo = m && m.message_type;
  return tipo === 2 || tipo === '2' || tipo === 'activity';
}

function ultimoMensaje(conv) {
  const lista = [];
  if (conv.last_non_activity_message && typeof conv.last_non_activity_message === 'object') {
    lista.push(conv.last_non_activity_message);
  }
  const msgs = Array.isArray(conv.messages) ? conv.messages : [];
  for (let i = 0; i < msgs.length; i++) {
    const m = msgs[i];
    if (m && typeof m === 'object' && !esActividad(m)) lista.push(m);
  }
  let mejor = null;
  let mejorTs = -1;
  for (let i = 0; i < lista.length; i++) {
    const ts = epochDe(lista[i].created_at || lista[i].timestamp);
    if (ts >= mejorTs) {
      mejor = lista[i];
      mejorTs = ts;
    }
  }
  return { mensaje: mejor, ts: mejorTs < 0 ? 0 : mejorTs };
}

function esPending(conv) {
  const st = String(conv.status == null ? '' : conv.status).toLowerCase();
  return st === 'pending' || st === '2';
}

