  for (const conv of payloadDe(raw)) {
    if (!esPending(conv)) continue;
    const id = String(conv.id || '');
    if (!id || vistos[id]) continue;
    const ultimo = ultimoMensaje(conv);
    const msgType = ultimo.mensaje ? ultimo.mensaje.message_type : undefined;
    const esSaliente = msgType === 'outgoing' || msgType === 1 || msgType === '1';
