session.motivo = 'reinicio_onu';
return salir('Se envió el comando de reinicio a tu ONU. El equipo tardará 1-2 minutos en reconectar.\n\nSi después de eso sigue igual, escribe y te paso con un asesor de soporte técnico.', [], 'reinicio_espera');

const estado = $('Armar estado equipo').first().json || {};
const session = Object.assign({}, estado.session || {});
let output = String(estado.output || '');
const menuItems = Array.isArray(estado.menu_items) ? estado.menu_items : [];
const raw = $input.first().json || {};
const wrapped = raw && raw.body && typeof raw.body === 'object' && !Array.isArray(raw.body) && (raw.statusCode || raw.headers);
const body = wrapped ? raw.body : raw;
const statusCode = Number(raw.statusCode || 0);

function filas(v) {
  if (Array.isArray(v)) return v;
  if (!v || typeof v !== 'object') return [];
  if (Array.isArray(v.data)) return v.data;
  if (v.data && typeof v.data === 'object' && Array.isArray(v.data.data)) return v.data.data;
  if (Array.isArray(v.ordenes)) return v.ordenes;
  return [];
}
function fechaCorta(v) {
  const text = String(v || '').trim().replace('T', ' ');
  return text ? text.slice(0, 16) : '';
}
function linea(r) {
  const tipo = r.tipo_servicio && typeof r.tipo_servicio === 'object' ? r.tipo_servicio.descripcion : '';
  const est = r.estado && typeof r.estado === 'object' ? r.estado.nombre : '';
  const fecha = fechaCorta(r.fecha_inicial_concertada || r.fecha_concertada_servicio || '');
  return [r.codigo || '', tipo || '', est || '', fecha].filter(Boolean).join(' — ');
}
function abierta(r) {
  if (!r || typeof r !== 'object') return false;
  const hecha = r.fecha_efectiva_servicio;
  return hecha === undefined || hecha === null || String(hecha).trim() === '';
}
function insertar(texto, bloque) {
  const marcas = ['\n\n¿Cómo quieres continuar?', '\n\nEscoge una opción.'];
  for (let i = 0; i < marcas.length; i++) {
    const at = texto.indexOf(marcas[i]);
    if (at !== -1) return texto.slice(0, at) + '\n\n' + bloque + texto.slice(at);
  }
  return texto + '\n\n' + bloque;
}

const fallo = statusCode >= 400 || !!raw.error || !body || typeof body !== 'object';
if (!fallo) {
  const abiertas = filas(body).filter(abierta).slice(0, 2);
  if (abiertas.length === 1) {
    output = insertar(output, 'Tienes una orden abierta: ' + (linea(abiertas[0]) || 'orden') + '.');
  } else if (abiertas.length > 1) {
    output = insertar(output, 'Tienes órdenes abiertas:\n' + abiertas.map(function (r, i) {
      return (i + 1) + '. ' + (linea(r) || 'orden');
    }).join('\n'));
  }
}

return [{
  json: Object.assign({}, estado, {
    session: session,
    output: output,
    menu_items: menuItems,
    route: 'menu'
  })
}];
